/**
 * Recovery metrics tracker
 */
class RecoveryMetricsTracker {
  private recoveryEvents: Array<{
  eventType: 'failure' | 'recovery_attempt' | 'recovery_success' | 'recovery_failure';
  timestamp: number;
  faultType: string;
    duration?: number;
    attempt?: number;
    details?: any;

}> = [];

  private activeFailures = new Map<string, {
  startTime: number;
  faultType: string;
    recoveryAttempts: number;

}>();

  recordFailure(faultType: string, details?: any): string {
    const failureId = `failure_${Date.now()}
_${Math.random().toString(36).substring(7)}`;
    const timestamp = Date.now();

    this.recoveryEvents.push({
  eventType: 'failure',
      timestamp,faultType,
      details,

});

    this.activeFailures.set(failureId, {
  startTime: timestamp,
      faultType,
      recoveryAttempts: 0,

});

    return failureId;
  }

  recordRecoveryAttempt(failureId: string, attempt: number, details?: any): void {
  const failure = this.activeFailures.get(failureId);
    if (failure) {
      failure.recoveryAttempts = attempt;

      this.recoveryEvents.push({
  eventType: 'recovery_attempt',
      timestamp: Date.now(),
      faultType: failure.faultType,
        attempt,
        details,

});
    }
  }

  recordRecoverySuccess(failureId: string, details?: any): void {
  const failure = this.activeFailures.get(failureId);
    if (failure) {
      const recoveryTime = Date.now() - failure.startTime;

      this.recoveryEvents.push({
  eventType: 'recovery_success',
      timestamp: Date.now(),
      faultType: failure.faultType,
        duration: recoveryTime,
        attempt: failure.recoveryAttempts,
        details,

});

      this.activeFailures.delete(failureId);
    }
  }

  recordRecoveryFailure(failureId: string, details?: any): void {
  const failure = this.activeFailures.get(failureId);
    if (failure) {
      this.recoveryEvents.push({
  eventType: 'recovery_failure',
      timestamp: Date.now(),
      faultType: failure.faultType,
        attempt: failure.recoveryAttempts,
        details,

});

      this.activeFailures.delete(failureId);
    }
  }

  getRecoveryAnalysis(): {
  totalFailures: number;
  successfulRecoveries: number;
    failedRecoveries: number;
  averageRecoveryTime: number;
    maxRecoveryTime: number;
  recoverySuccessRate: number;
    averageRecoveryAttempts: number;
  faultTypeBreakdown: Record<string, number>;

} {
  const failures = this.recoveryEvents.filter(e => e.eventType === 'failure');const successfulRecoveries = this.recoveryEvents.filter(e => e.eventType === 'recovery_success');const failedRecoveries = this.recoveryEvents.filter(e => e.eventType === 'recovery_failure');const recoveryTimes = successfulRecoveries.filter(r => r.duration !== undefined)
      .map(r => r.duration || 0);

    const faultTypeBreakdown: Record<string, number> = {
};
    failures.forEach(f => {
  faultTypeBreakdown[f.faultType] = (faultTypeBreakdown[f.faultType] || 0) + 1;

});

    const recoveryAttempts = successfulRecoveries
      .filter(r => r.attempt !== undefined)
      .map(r => r.attempt || 0);

    return {
  totalFailures: failures.length,
      successfulRecoveries: successfulRecoveries.length,
      failedRecoveries: failedRecoveries.length,
      averageRecoveryTime: recoveryTimes.length > 0
        ? recoveryTimes.reduce((sum, time) => sum + time, 0) / recoveryTimes.length
        : 0,
      maxRecoveryTime: recoveryTimes.length > 0 ? Math.max(...recoveryTimes) : 0,
      recoverySuccessRate: failures.length > 0
        ? successfulRecoveries.length / failures.length
        : 0,
      averageRecoveryAttempts: recoveryAttempts.length > 0
        ? recoveryAttempts.reduce((sum, attempts) => sum + attempts, 0) / recoveryAttempts.length
        : 0,
      faultTypeBreakdown,

};
  }

  getEvents() {
  return [...this.recoveryEvents];

}

  reset(): void {
  this.recoveryEvents = [];
    this.activeFailures.clear();

}
}

/**
 * Resilient WebSocket client with recovery mechanisms
 */
class ResilientWebSocketClient extends EventEmitter {
  private ws: WebSocket.WebSocket | null = null;
  private connected = false;
  private reconnectionAttempts = 0;
  private maxReconnectionAttempts = 10;
  private reconnectionDelay = 1000;
  private backoffMultiplier = 1.5;
  private messageQueue: ConversationalMessage[] = [];
  private recoveryTracker = new RecoveryMetricsTracker();
  private circuitBreakerOpen = false;
  private circuitBreakerFailures = 0;
  private circuitBreakerThreshold = 5;
  private circuitBreakerTimeout = 10000;

  constructor(
    private url: string,
    private options: {
      autoReconnect?: boolean;
      maxReconnectionAttempts?: number;
      queueMessages?: boolean;
      circuitBreakerEnabled?: boolean;
      clientId?: string;

} = {}
  ) {
  super();
    this.maxReconnectionAttempts = options.maxReconnectionAttempts || 10;
    this.options.autoReconnect = options.autoReconnect ?? true;
    this.options.queueMessages = options.queueMessages ?? true;
    this.options.circuitBreakerEnabled = options.circuitBreakerEnabled ?? true;

}

  async connect(): Promise<void>  {
  if (this.circuitBreakerOpen) {
      throw new Error('Circuit breaker is open, connection not allowed');
}
return new Promise((resolve, reject) => {
  try {
        this.ws = new WebSocket.WebSocket(this.url, {
  headers: this.options.clientId ? { 'X-Client-ID': this.options.clientId 
} : {},});
    const connectionTimeout = setTimeout(() => {
  if (this.ws) {
            this.ws.terminate();

}
          this.handleConnectionFailure(new Error('Connection timeout'));
reject(new Error('Connection timeout'));}, 10000);this.ws.on('open', () => {
  clearTimeout(connectionTimeout);this.connected = true;
          this.reconnectionAttempts = 0;
          this.circuitBreakerFailures = 0;
          this.circuitBreakerOpen = false;

          // Process queued messages
          this.processQueuedMessages();

          this.emit('connected');
resolve();
});

        this.ws.on('message', (data: WebSocket.RawData) => {try {const message = JSON.parse(Buffer.from(data as ArrayBuffer).toString('utf8')) as ConversationalMessage;this.emit('message', message);} catch (error) {this.emit('error', new Error(`Failed to parse message: ${error}`));
          }
        });

        this.ws.on('error', (error: Error) => {
  clearTimeout(connectionTimeout);this.handleConnectionFailure(error);
          reject(error);

});

        this.ws.on('close', (code: number, reason: Buffer) => {
  clearTimeout(connectionTimeout);this.connected = false;
          this.emit('disconnected', { code, reason: reason.toString() 
});if (this.options.autoReconnect && code !== 1000) {
  this.scheduleReconnection();

}
        });

      } catch (error) {
  this.handleConnectionFailure(error as Error);
        reject(error);

}
    });
  }

  private handleConnectionFailure(error: Error): void {
  this.connected = false;
    this.circuitBreakerFailures++;

    const failureId = this.recoveryTracker.recordFailure('connection_failure', {error: error.message,
      attempts: this.reconnectionAttempts,

});

    if (this.options.circuitBreakerEnabled &&
        this.circuitBreakerFailures >= this.circuitBreakerThreshold) {
  this.openCircuitBreaker();

}

    this.emit('connection-failure', { error, failureId });}private openCircuitBreaker(): void {
  this.circuitBreakerOpen = true;

    setTimeout(() => {
      this.circuitBreakerOpen = false;
      this.circuitBreakerFailures = 0;
      this.emit('circuit-breaker-closed');
}, this.circuitBreakerTimeout);this.emit('circuit-breaker-opened');}
private scheduleReconnection(): void {
  if (this.reconnectionAttempts >= this.maxReconnectionAttempts || this.circuitBreakerOpen) {
      const failureId = this.recoveryTracker.recordFailure('max_reconnection_attempts', {attempts: this.reconnectionAttempts,
      circuitBreakerOpen: this.circuitBreakerOpen,

});
      this.recoveryTracker.recordRecoveryFailure(failureId, 'Maximum reconnection attempts exceeded');this.emit('recovery-failed', { reason: 'max_attempts_exceeded' });return;}

    this.reconnectionAttempts++;
    const delay = Math.min(
      this.reconnectionDelay * Math.pow(this.backoffMultiplier, this.reconnectionAttempts - 1),
      30000 // Max 30 seconds
    );

    this.emit('reconnection-scheduled', {
  attempt: this.reconnectionAttempts,
      delay,
      maxAttempts: this.maxReconnectionAttempts,

});

    setTimeout(async () => {
      const failureId = this.recoveryTracker.recordFailure('reconnection_attempt', {attempt: this.reconnectionAttempts,});

      this.recoveryTracker.recordRecoveryAttempt(failureId, this.reconnectionAttempts);

      try {
  await this.connect();
        this.recoveryTracker.recordRecoverySuccess(failureId, {
  attempt: this.reconnectionAttempts,
          delay,

});
        this.emit('recovery-success', { attempt: this.reconnectionAttempts });} catch (error) {
  this.emit('reconnection-failed', {attempt: this.reconnectionAttempts,
      error,

});
        // Will automatically schedule next attempt via close event
      }
    }, delay);
  }

  async sendMessage(message: ConversationalMessage): Promise<void>  {
  if (!this.connected || !this.ws) {
      if (this.options.queueMessages) {
        this.messageQueue.push(message);
        this.emit('message-queued', message);return;
} else {
        throw new Error('WebSocket not connected and message queuing disabled');}}

    try {
  this.ws.send(JSON.stringify(message));
      this.emit('message-sent', message);
} catch (error) {
  if (this.options.queueMessages) {
        this.messageQueue.push(message);
        this.emit('message-queued', message);
} else {
  throw error;

}
    }
  }

  private async processQueuedMessages(): Promise<void>  {
  if (this.messageQueue.length === 0) return;

    this.emit('processing-queue', { queueSize: this.messageQueue.length 
});const messages = [...this.messageQueue];this.messageQueue = [];

    for (const message of messages) {
  try {
        await this.sendMessage(message);
        await new Promise(resolve => setTimeout(resolve, 10)); // Small delay between messages

} catch (error) {
        this.emit('queue-processing-error', { message, error });}}
  }

  async forceReconnect(): Promise<void>  {
  if (this.ws) {
      this.ws.close();

}
    this.reconnectionAttempts = 0;
    await this.connect();
  }

  async disconnect(): Promise<void>  {
  this.options.autoReconnect = false;
    if (this.ws) {
      this.ws.close(1000, 'Normal closure');
}}

  getRecoveryMetrics(): any {
  return this.recoveryTracker.getRecoveryAnalysis();

}

  getQueueSize(): number {
  return this.messageQueue.length;

}

  isConnected(): boolean {
  return this.connected;

}

  isCircuitBreakerOpen(): boolean {
  return this.circuitBreakerOpen;

}

  reset(): void {
  this.messageQueue = [];
    this.reconnectionAttempts = 0;
    this.circuitBreakerFailures = 0;
    this.circuitBreakerOpen = false;
    this.recoveryTracker.reset();

}
}

